-- Release rehearsal: generate live's pre-0034 public-schema DDL from the catalog.
-- READ-ONLY. Run against LIVE (it only SELECTs), save the "s" column of each query, in order, as
-- live_pre0034_baseline.sql, and apply that file to the staging project after 00-reset-to-live-baseline.sql.
-- Then run 10-fingerprint.sql on both projects: every section must match (function ACL lists can differ in
-- item ORDER only; compare the sets).

-- Query 1: tables, constraints (non-FK first, then FK), indexes, RLS, replica identity, owners.
with t as (select c.oid, c.relname, c.relrowsecurity, c.relforcerowsecurity, c.relreplident from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p'))
select 1 ord, t.relname k, 'create table public.'||quote_ident(t.relname)||' ('||string_agg('  '||quote_ident(a.attname)||' '||format_type(a.atttypid,a.atttypmod)
 ||case when a.attidentity='a' then ' generated always as identity' when a.attidentity='d' then ' generated by default as identity' else '' end
 ||case when a.attgenerated='s' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') stored' when d.adbin is not null then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end
 ||case when a.attnotnull then ' not null' else '' end, ', ' order by a.attnum)||');' s
from t join pg_attribute a on a.attrelid=t.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=t.oid and d.adnum=a.attnum group by t.relname
union all select 2, t.relname||co.conname, 'alter table public.'||quote_ident(t.relname)||' add constraint '||quote_ident(co.conname)||' '||pg_get_constraintdef(co.oid)||';' from t join pg_constraint co on co.conrelid=t.oid where co.contype in ('p','u','c','x')
union all select 3, t.relname||co.conname, 'alter table public.'||quote_ident(t.relname)||' add constraint '||quote_ident(co.conname)||' '||pg_get_constraintdef(co.oid)||';' from t join pg_constraint co on co.conrelid=t.oid where co.contype='f'
union all select 4, i.indexrelid::regclass::text, pg_get_indexdef(i.indexrelid)||';' from t join pg_index i on i.indrelid=t.oid where not exists(select 1 from pg_constraint co where co.conindid=i.indexrelid)
union all select 5, t.relname, 'alter table public.'||quote_ident(t.relname)||' enable row level security;' from t where t.relrowsecurity
union all select 5, t.relname||'f', 'alter table public.'||quote_ident(t.relname)||' force row level security;' from t where t.relforcerowsecurity
union all select 5, t.relname||'r', 'alter table public.'||quote_ident(t.relname)||' replica identity '||case t.relreplident when 'f' then 'full' when 'n' then 'nothing' end||';' from t where t.relreplident in ('f','n')
union all select 6, t.relname||' owner', 'alter table public.'||quote_ident(t.relname)||' owner to '||quote_ident(pg_get_userbyid(c.relowner))||';' from t join pg_class c on c.oid=t.oid where pg_get_userbyid(c.relowner)<>'postgres'
order by 1,2;

-- Query 2: functions, policies, triggers, table/column/function grants (+ informational schema ACL lines).
with f as (select p.oid, p.proname, pg_get_function_identity_arguments(p.oid) args, p.proacl from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
t as (select c.oid, c.relname, c.relacl from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p'))
select * from (
select 20 ord, f.proname||f.args k, pg_get_functiondef(f.oid)||';' s from f
union all select 30, pol.tablename||pol.policyname, 'create policy '||quote_ident(pol.policyname)||' on public.'||quote_ident(pol.tablename)||' as '||lower(pol.permissive)||' for '||lower(pol.cmd)||' to '||(select string_agg(quote_ident(r),', ') from unnest(pol.roles) r)||coalesce(' using ('||pol.qual||')','')||coalesce(' with check ('||pol.with_check||')','')||';' from pg_policies pol where pol.schemaname='public'
union all select 40, c.relname||tg.tgname, pg_get_triggerdef(tg.oid)||';' from pg_trigger tg join t c on c.oid=tg.tgrelid where not tg.tgisinternal
union all select 50, t.relname, 'revoke all on table public.'||quote_ident(t.relname)||' from public, anon, authenticated, service_role;' from t
union all select 51, t.relname||a.privilege_type||a.grantee::regrole::text, 'grant '||a.privilege_type||' on table public.'||quote_ident(t.relname)||' to '||case when a.grantee=0 then 'public' else quote_ident(a.grantee::regrole::text) end||case when a.is_grantable then ' with grant option' else '' end||';' from t cross join lateral aclexplode(t.relacl) a where a.grantee<>(select relowner from pg_class where oid=t.oid)
union all select 52, t.relname||att.attname||a.privilege_type, 'grant '||a.privilege_type||' ('||quote_ident(att.attname)||') on table public.'||quote_ident(t.relname)||' to '||quote_ident(a.grantee::regrole::text)||';' from t join pg_attribute att on att.attrelid=t.oid and att.attacl is not null cross join lateral aclexplode(att.attacl) a
union all select 60, f.proname||f.args, 'revoke all on function public.'||quote_ident(f.proname)||'('||f.args||') from public, anon, authenticated, service_role;' from f where f.proacl is not null
union all select 61, f.proname||f.args||a.privilege_type||a.grantee::text, 'grant execute on function public.'||quote_ident(f.proname)||'('||f.args||') to '||case when a.grantee=0 then 'public' else quote_ident(a.grantee::regrole::text) end||';' from f cross join lateral aclexplode(f.proacl) a where a.grantee<>(select proowner from pg_proc where oid=f.oid)
union all select 90, 'nsp', '-- public nspacl '||coalesce((select nspacl::text from pg_namespace where nspname='public'),'null')||' owner '||(select pg_get_userbyid(nspowner) from pg_namespace where nspname='public')
union all select 91, d.defaclrole::regrole::text||d.defaclobjtype::text, '-- defacl '||d.defaclrole::regrole::text||' '||d.defaclobjtype::text||' '||d.defaclacl::text from pg_default_acl d where d.defaclnamespace=(select oid from pg_namespace where nspname='public')
) x order by ord, k;
